<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '@/services/api'
const props=withDefaults(defineProps<{limit?:number;destination?:string;activity?:string;editing?:boolean}>(),{limit:6,destination:'',activity:'',editing:false});const tours=ref<any[]>([])
onMounted(async()=>{const q=new URLSearchParams();if(props.destination)q.set('destination',props.destination);if(props.activity)q.set('activity',props.activity);const r=await api<any>(`/api/public/travel/search?${q}`).catch(()=>({tours:[]}));tours.value=(r.tours||[]).slice(0,props.limit)})
function money(v:any,c='USD'){return new Intl.NumberFormat('en-US',{style:'currency',currency:c}).format(Number(v||0))}
</script><template><div><div v-if="!tours.length" class="empty">{{ editing?'Publish tours to preview the catalogue.':'No tours are currently available.' }}</div><div v-else class="grid"><RouterLink v-for="tour in tours" :key="tour.id" :to="editing?'':`/travel/${tour.slug}`" class="card"><img v-if="tour.featuredImageUrl" :src="tour.featuredImageUrl"><div v-else class="placeholder">🌴</div><div><small>{{ tour.destination?.name }}</small><h3>{{ tour.name }}</h3><p>{{ tour.shortDescription }}</p><footer><strong>{{ money(tour.adultPrice,tour.currency) }}</strong><span>View tour →</span></footer></div></RouterLink></div></div></template><style scoped>.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{overflow:hidden;border:1px solid #dbe5e3;border-radius:19px;background:white;color:#153334;text-decoration:none;box-shadow:0 10px 30px #0b575711}.card>img,.placeholder{width:100%;height:190px;object-fit:cover}.placeholder{display:grid;place-items:center;background:#dff1ed;font-size:3rem}.card>div:last-child{padding:18px}.card small{color:#087f7b;font-weight:900}.card h3{margin:.3rem 0}.card p{color:#657775;font-size:.85rem}.card footer{display:flex;justify-content:space-between;border-top:1px solid #edf1f0;padding-top:14px}.card footer span{color:#087f7b;font-weight:800}.empty{padding:40px;text-align:center;border:1px dashed #bbcfcf;border-radius:16px}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style>
